const greet = BooleanSetting("Greet", "Log a greeting when the module turns on", true);

const mod = module.create({
    name: "My Module",
    description: "Example module with one setting",
    category: "SCRIPTS",
    settings: [greet],
    onEnable:  () => { if (greet.value) script.log("enabled"); },
    onDisable: () => script.log("disabled"),
});

module.export(mod);

const seconds = SliderSetting("Interval (s)", "How often to run, in seconds", 1, 30, 5);

const mod = module.create({
    name: "Tick Loop",
    description: "Runs on a timer while enabled",
    category: "SCRIPTS",
    settings: [seconds],
    onEnable:  () => script.log("enabled"),
    onDisable: () => script.log("disabled"),
});

let ticks = 0;
on("tick", () => {
    if (++ticks < seconds.value * 20) return;
    ticks = 0;
    script.log("tick loop fired");
});

module.export(mod);

const delay = SliderSetting("Delay (ms)", "Pause between actions", 0, 2000, 500);

const m = macro.create({
    name: "My Macro",
    description: "A starter script macro",
    subcategory: "Scripts",
    settings: [delay],
});

m.hud(() => "State: " + m.currentState());

m.onEnable(() => {
    script.log("macro enabled");
    m.setState("MOVE");
});

// macros are state machines — onState runs each tick while in that state
m.onState("MOVE", () => {
    // do your thing, then switch states with m.setState(...)
});

m.onDisable(() => script.log("macro disabled"));

macro.export(m);

const toggle = module.create("Chest ESP", "Highlights nearby chests");
on("tick", () => {
    if (!toggle.enabled()) return;
    for (const b of world.findBlocks("chest", 24)) esp.box(b, 0x00ffaa);
});

on("tick", () => {
    const near = entity.players(16);
    if (near.length > 0) notification.push("AFK", near[0].name + " is nearby!");
});

const helper = helper.create("AutoSell");
helper.onTrigger(() => player.inventoryFull());
helper.run(async () => {
    await nav.walkTo(helper.config.npcPos);
    await inventory.open("Trades");
    await inventory.clickSlot(49);
    await sleep(300);
    inventory.close();
});

let rate = 0;
on("powderGain", (amt) => rate += amt);
setInterval(() => rate *= 0.98, 1000);
on("hudRender", () => render.text("Powder/h: " + util.format(rate * 3600), 10, 40));

on("chat", (msg) => {
    if (!msg.includes("SLAYER QUEST STARTED")) return;
    const boss = entity.mobs(32).find(m => m.name.includes("Voidgloom"));
    if (boss) combat.aim(boss);
});

const plots = ["plot_1", "plot_2", "plot_3"];
let i = 0;
setInterval(() => {
    script.chat("/warp " + plots[i++ % plots.length]);
}, 45000 + math.random(0, 5000));

on("tick", () => {
    for (const spot of skyblock.hotspots(48)) {
        esp.box(spot.pos, spot.perfect ? 0xffd700 : 0x4488ff);
        if (spot.perfect) notification.push("Hotspot", "Perfect hotspot nearby!");
    }
});

let ready = true;
on("swing", () => { ready = false; setTimeout(() => ready = true, 4000); });
on("hudRender", () => { if (ready) render.text("TREECAP READY", 10, 60); });

module.create("Storage Sorter", "Sorts open storage by value").onEnable(async () => {
    const slots = inventory.slots().sort((a, b) => skyblock.price(b.item) - skyblock.price(a.item));
    for (const s of slots) { await inventory.clickSlot(s.index); await sleepTicks(2); }
});

on("entitySpawn", (e) => {
    if (!e.name.includes("Worm")) return;
    util.notify("Worm spawned!");
    esp.box(e, 0xff4444, 5000);
});

on("chat", (msg) => {
    if (msg.includes("has left the party")) script.chat("/p transfer " + client.username());
});

$preferred = $env:POLINEX_PREFERRED
$sessions = $sessionManager.GetSessions()
$session = $null
if ($preferred) {
    foreach ($s in $sessions) {
        if ($s.SourceAppUserModelId -eq $preferred) { $session = $s; break }
    }
}
if ($session -eq $null) {
    foreach ($s in $sessions) {
        try {
            if ($s.GetPlaybackInfo().PlaybackStatus.ToString() -eq 'Playing') { $session = $s; break }
        } catch {}
    }
}
if ($session -eq $null) { $session = $sessionManager.GetCurrentSession() }

$sessions = $sessionManager.GetSessions()
foreach ($s in $sessions) {
    try {
        $props = Await ($s.TryGetMediaPropertiesAsync()) ([Windows.Media.Control.GlobalSystemMediaTransportControlsSessionMediaProperties])
        if ($props -eq $null) { continue }
        $timeline = $s.GetTimelineProperties()
        $playback = $s.GetPlaybackInfo()
        $artist = if ($props.Artist) { $props.Artist } else { '' }
        $title = if ($props.Title) { $props.Title } else { '' }
        $album = if ($props.AlbumTitle) { $props.AlbumTitle } else { '' }
        $durationMs = [long]$timeline.EndTime.TotalMilliseconds
        $statusRaw = $playback.PlaybackStatus.ToString()
        $ctrl = $playback.Controls
        $playEnabled = $ctrl.IsPlayEnabled
        $pauseEnabled = $ctrl.IsPauseEnabled
        $isPlaying = $false
        if ($statusRaw -eq 'Playing' -and -not $playEnabled) { $isPlaying = $true }
        elseif ($statusRaw -eq 'Playing' -and $pauseEnabled) { $isPlaying = $true }
        elseif ($playEnabled -and -not $pauseEnabled) { $isPlaying = $false }
        else { $isPlaying = ($statusRaw -eq 'Playing') }
        $status = if ($isPlaying) { 'Playing' } else { 'Paused' }
        $rawPosMs = [double]$timeline.Position.TotalMilliseconds
        if ($isPlaying) {
            $ageMs = ([DateTimeOffset]::Now - $timeline.LastUpdatedTime).TotalMilliseconds
            if ($ageMs -gt 0 -and $ageMs -lt 60000) {
                $rawPosMs = $rawPosMs + $ageMs
            }
        }
        $positionMs = [long]$rawPosMs
        $source = $s.SourceAppUserModelId
        Write-Output "$artist`t$title`t$album`t$durationMs`t$positionMs`t$status`t$source"
    } catch { continue }
}

#version 330 core
layout (location = 0) in vec2 aPos;
out vec2 fragCoord;
uniform vec2 iResolution;

void main() {
    fragCoord = (aPos * 0.5 + 0.5) * iResolution;
    gl_Position = vec4(aPos, 0.0, 1.0);
}

#version 330 core
layout (location = 0) in vec2 aPos;
layout (location = 1) in vec2 aTexCoord;
out vec2 TexCoord;

void main() {
    gl_Position = vec4(aPos, 0.0, 1.0);
    TexCoord = aTexCoord;
}

#version 330 core
out vec4 FragColor;
in vec2 TexCoord;

uniform sampler2D image;
uniform vec2 resolution;
uniform float blurSize;

void main() {
    float Pi = 6.28318530718;
    float Directions = 32.0;
    float Quality = 8.0;
    float Size = blurSize;

    vec2 Radius = Size / resolution;
    vec2 uv = TexCoord;
    vec4 Color = texture(image, uv);

    for(float d = 0.0; d < Pi; d += Pi / Directions) {
        for(float i = 1.0 / Quality; i <= 1.0; i += 1.0 / Quality) {
            Color += texture(image, uv + vec2(cos(d), sin(d)) * Radius * i);
        }
    }

    // Total samples = 1 (center) + Directions * Quality (loop samples)
    // = 1 + 16 * 3 = 49
    Color /= (Quality * Directions + 1.0);
    FragColor = Color;
}

#version 330 core
layout (location = 0) in vec2 aPos;
layout (location = 1) in vec2 aTexCoords;
out vec2 TexCoords;
void main() {
    gl_Position = vec4(aPos.x, aPos.y, 0.0, 1.0);
    TexCoords = aTexCoords;
}

#version 330 core
out vec4 FragColor;
in vec2 TexCoords;
uniform sampler2D screenTexture;
void main() {
    FragColor = texture(screenTexture, TexCoords);
}
